#include <stdio.h>
typedef struct Axis6W5Row { unsigned int lane, checkpoint, shadow; int delta; } Axis6W5Row;
typedef struct Axis6W5Agg { unsigned int checkpoint[5], shadow[5]; int value[5]; } Axis6W5Agg;
static unsigned int mix5(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6)+(h>>2); return h; }
static void clear5(Axis6W5Agg* a){ for(int i=0;i<5;++i){ a->checkpoint[i]=0u; a->shadow[i]=0u; a->value[i]=0; } }
static void absorb5(Axis6W5Agg* a,const Axis6W5Row* r){ unsigned int lane=r->lane%5u; if(r->checkpoint<a->checkpoint[lane]) return; if(r->checkpoint>a->checkpoint[lane]){ a->checkpoint[lane]=r->checkpoint; a->shadow[lane]=r->shadow; a->value[lane]=r->delta; return;} if(r->shadow>a->shadow[lane]){ a->shadow[lane]=r->shadow; a->value[lane]=r->delta; } else if(r->shadow==a->shadow[lane]) a->value[lane]+=r->delta; }
static unsigned int sig5(const Axis6W5Agg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<5u; ++lane){ h=mix5(h,lane+1u); h=mix5(h,a->checkpoint[lane]); h=mix5(h,a->shadow[lane]); h=mix5(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const Axis6W5Row rows[]={{0u,2u,1u,4},{1u,3u,2u,5},{2u,1u,3u,7},{3u,2u,4u,3},{4u,1u,2u,6},{0u,5u,2u,6},{1u,4u,3u,-1},{2u,5u,2u,8},{3u,4u,5u,2},{4u,5u,3u,4},{0u,5u,2u,-2},{1u,4u,3u,4},{2u,5u,4u,1},{3u,4u,5u,-3},{4u,5u,3u,-1},{0u,6u,4u,5},{1u,6u,5u,3},{2u,6u,4u,6},{3u,6u,6u,1},{4u,6u,2u,2}}; Axis6W5Agg d,p; clear5(&d); for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i) absorb5(&d,&rows[i]); clear5(&p); for(unsigned int checkpoint=1u;checkpoint<=6u;++checkpoint) for(unsigned int lane=0;lane<5u;++lane) for(unsigned int shadow=1u;shadow<=6u;++shadow){ int merged=0,saw=0; for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i){ if(rows[i].checkpoint!=checkpoint || rows[i].lane%5u!=lane || rows[i].shadow!=shadow) continue; merged+=rows[i].delta; saw=1; } if(saw){ Axis6W5Row row={lane,checkpoint,shadow,merged}; absorb5(&p,&row); } } unsigned int sd=sig5(&d), sp=sig5(&p); printf("%u %u %u\n", sd, sp, (sd==sp)?1u:0u); return 0; }
